public class GradientStepTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static double r6(double x) {
        return Math.round(x * 1e6) / 1e6;
    }

    public static void main(String[] args) {
        check("step(0.5, {2}, {4}, 0.25)", r6(3.5),
                r6(GradientStep.step(0.5, new double[]{2}, new double[]{4}, 0.25)));
        check("step(0, {1,2,3}, {2,4,6}, 0.1) rounded to 6dp", r6(1.866667),
                r6(GradientStep.step(0.0, new double[]{1, 2, 3}, new double[]{2, 4, 6}, 0.1)));
        check("at the optimum the weight does not move", r6(2.0),
                r6(GradientStep.step(2.0, new double[]{1, 2, 3}, new double[]{2, 4, 6}, 0.1)));
        check("step(1, {1,2}, {3,5}, 0.05)", r6(1.4),
                r6(GradientStep.step(1.0, new double[]{1, 2}, new double[]{3, 5}, 0.05)));
        check("step(-1, {1,2}, {2,4}, 0.1)", r6(0.5),
                r6(GradientStep.step(-1.0, new double[]{1, 2}, new double[]{2, 4}, 0.1)));
        check("step(1, {1,2,3,4}, {2,3,5,9}, 0.01)", r6(1.145),
                r6(GradientStep.step(1.0, new double[]{1, 2, 3, 4}, new double[]{2, 3, 5, 9}, 0.01)));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

