public class GradientStep {

    public static double step(double w, double[] xs, double[] ys, double lr) {
        double gradSum = 0.0;
        for (int i = 0; i < xs.length; i++) {
            gradSum += 2.0 * xs[i] * (w * xs[i] - ys[i]);
        }
        double gradient = gradSum / xs.length;
        return w - lr * gradient;
    }
}
